const succeededAttempt = `-- name: SucceededAttempt :one
SELECT id, payment_id, provider, status, external_id, created_at, updated_at, br_code, checks, next_check_at, escalated_at FROM payment_attempts WHERE payment_id = $1 AND status = 'succeeded'
`

// At most one: a payment has one live attempt at a time.
func (q *Queries) SucceededAttempt(ctx context.Context, paymentID pgtype.UUID) (PaymentAttempt, error) {
	row := q.db.QueryRow(ctx, succeededAttempt, paymentID)
	var i PaymentAttempt
	err := row.Scan(
		&i.ID,
		&i.PaymentID,
		&i.Provider,
		&i.Status,
		&i.ExternalID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.BrCode,
		&i.Checks,
		&i.NextCheckAt,
		&i.EscalatedAt,
	)
	return i, err
}

const succeededRefunds = `-- name: SucceededRefunds :one
SELECT coalesce(sum(amount), 0)::bigint FROM refunds WHERE payment_id = $1 AND status = 'succeeded'
`

func (q *Queries) SucceededRefunds(ctx context.Context, paymentID pgtype.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, succeededRefunds, paymentID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const updateAttempt = `-- name: UpdateAttempt :exec
UPDATE payment_attempts
SET status = $1, external_id = $2, br_code = $3, updated_at = $4,
    checks = $5, next_check_at = $6
WHERE id = $7
`

type UpdateAttemptParams struct {
	Status      string
	ExternalID  pgtype.Text
	BrCode      pgtype.Text
	UpdatedAt   pgtype.Timestamptz
	Checks      int32
	NextCheckAt pgtype.Timestamptz
	ID          pgtype.UUID
}

func (q *Queries) UpdateAttempt(ctx context.Context, arg UpdateAttemptParams) error {
	_, err := q.db.Exec(ctx, updateAttempt,
		arg.Status,
		arg.ExternalID,
		arg.BrCode,
		arg.UpdatedAt,
		arg.Checks,
		arg.NextCheckAt,
		arg.ID,
	)
	return err
}

const updatePaymentStatus = `-- name: UpdatePaymentStatus :one
UPDATE payments SET status = $1, version = version + 1, updated_at = $2, expiry_check_at = NULL
WHERE id = $3
RETURNING version
`

type UpdatePaymentStatusParams struct {
	Status    string
	UpdatedAt pgtype.Timestamptz
	ID        pgtype.UUID
}

// Every status after pending is final for expiry, so the payment leaves its queue.
func (q *Queries) UpdatePaymentStatus(ctx context.Context, arg UpdatePaymentStatusParams) (int32, error) {
	row := q.db.QueryRow(ctx, updatePaymentStatus, arg.Status, arg.UpdatedAt, arg.ID)
	var version int32
	err := row.Scan(&version)
	return version, err
}

